  "key_points": [{"point": "关键点（一句话）", "evidence": "支撑该点的原文关键句，不超过 60 字"}],
  "todos": [{"task": "待办事项", "owner": "负责人或空字符串", "due": "时间要求或空字符串"}],
  "decisions": ["已达成的决定/结论"],
